	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/shelves/{shelfId}/comments", wrapper.CreateShelfComment)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/comments/{commentId}", wrapper.DeleteComment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/comments/by-ids", wrapper.GetCommentsByIds)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/feed", wrapper.GetFeed)
